templateCss:
.trend-card-container.elec {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 10px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #38bdf8;
  padding: 16px 20px 12px 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
}
.trend-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.trend-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
}
.trend-icon { font-size: 16px; }
.trend-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 20px;
}
.trend-badge.charging {
  color: #64B856;
  border: 1.5px solid #64B856;
  background: rgba(100, 184, 86, 0.12);
}
.trend-badge.discharging {
  color: #f7d048;
  border: 1.5px solid #f7d048;
  background: rgba(247, 208, 72, 0.12);
}
.trend-kpi-bar {
  display: flex;
  justify-content: space-around;
  align-items: center;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(100, 184, 86, 0.12);
  border-radius: 8px;
  padding: 6px 12px;
  margin: 8px 0;
}
.kpi-col {
  display: flex;
  flex-direction: column;
  align-items: center;
}
.kpi-lbl { font-size: 10px; font-weight: 700; color: #64748b; letter-spacing: 0.5px; }
.kpi-val-group { display: flex; align-items: baseline; gap: 4px; }
.kpi-num { font-size: 20px; font-weight: 800; line-height: 1.1; }
.kpi-num.v-color { color: #38bdf8; }
.kpi-num.i-color { color: #64B856; }
.kpi-num.p-color { color: #f1f5f9; }
.kpi-unit { font-size: 12px; font-weight: 600; color: #94a3b8; }
.kpi-divider { width: 1px; height: 26px; background: rgba(148, 163, 184, 0.15); }
.chart-wrapper {
  width: 100%;
  flex: 1;
  min-height: 110px;
  position: relative;
}
.chart-wrapper canvas {
  width: 100%;
  height: 100%;
  display: block;
}
.trend-footer {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #64748b;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  padding-top: 6px;
  margin-top: 4px;
}

controllerScript:
// Controller Script: SCADA - Dinámica de Bus DC y Corrientes Telecom (100% Telemetría Real)
self.onInit = function() {
  self.ctx.$scope.drawChart = self.drawChart;
  self.onDataUpdated();
};

self.onResize = function() {
  self.drawChart();
};

self.onDataUpdated = function() {
  var data = self.ctx.data;
  var curV = 0.0, curIbat = 0.0, curIrect = 0.0, curIload = 0.0, loadKw = 0.0;
  var vSeries = [], iBatSeries = [], iRectSeries = [], loadSeries = [], iLoadSeries = [];

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (item.data && item.data.length > 0) {
        var rawVal = item.data[item.data.length - 1][1];
        var v = parseFloat(rawVal);
        var k = (item.dataKey.name || item.dataKey.label || '').toLowerCase();

        if (!isNaN(v)) {
          if (k === 'rectifier_voltage' || k === 'battery_voltage' || k === 'vbat_promedio') {
            if (v > 0) {
              curV = v;
              vSeries = item.data;
            }
          }
          else if (k === 'rectifier_current') {
            curIrect = v;
            iRectSeries = item.data;
          }
          else if (k === 'battery_current' || k === 'ibat_total' || k === 'ibat') {
            curIbat = v;
            iBatSeries = item.data;
          }
          else if (k === 'load_dc_current') {
            curIload = Math.max(0, v);
            iLoadSeries = (item.data || []).map(function(p) {
              return [p[0], Math.max(0, parseFloat(p[1]) || 0)];
            });
          }
          else if (k === 'load_dc_voltage') {
            if (v > 0) curV = v;
          }
          else if (k === 'load_power_kw' || k === 'load_dc_power_kw' || k === 'demanda_carga_kw') {
            loadKw = Math.max(loadKw, Math.max(0, v));
            loadSeries = item.data;
          }
        }
      }
    }
  }

  loadKw = Math.max(0, loadKw);
  if (curIload === 0 && curV > 0) curIload = (loadKw * 1000 / curV);

  // Construir serie calculada de corriente de carga si no vino load_dc_current directa
  if (iLoadSeries.length === 0 && loadSeries && loadSeries.length > 0) {
    iLoadSeries = loadSeries.map(function(p) {
      var pKw = Math.max(0, parseFloat(p[1]) || 0);
      var a = curV > 0 ? (pKw * 1000 / curV) : 0;
      return [p[0], a];
    });
  }

  self.latestV = curV;
  self.latestIload = curIload;
  self.latestIrect = curIrect;
  self.latestIbat = curIbat;
  self.latestLoadKw = loadKw;

  self.vSeriesData = vSeries;
  self.iLoadSeriesData = iLoadSeries;
  self.iRectSeriesData = iRectSeries;
  self.iBatSeriesData = iBatSeries;

  var isIndustrial = (curV > 200.0);
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (!container) return;

  var elTitle = container.querySelector('#dc-trend-title');
  var elBadge = container.querySelector('#dc-trend-badge');
  var elV = container.querySelector('#vbat-live-val');
  var elIload = container.querySelector('#iload-live-val');
  var elIrect = container.querySelector('#irect-live-val');
  var elIbat = container.querySelector('#ibat-live-val');
  var elReg = container.querySelector('#trend-regimen-text');

  if (isIndustrial) {
    if (elTitle) elTitle.textContent = 'TENDENCIA TENSIÓN Y CORRIENTE BESS INDUSTRIAL';
    if (elBadge) {
      elBadge.textContent = '750V DC BESS';
      elBadge.className = 'trend-badge';
    }

    var elLblLoad = container.querySelector('#kpi-lbl-load');
    var elUnitLoad = container.querySelector('#kpi-unit-load');
    var elLblRect = container.querySelector('#kpi-lbl-rect');
    var elUnitRect = container.querySelector('#kpi-unit-rect');
    var elLblBat = container.querySelector('#kpi-lbl-bat');
    var elUnitBat = container.querySelector('#kpi-unit-bat');
    var elAxisFoot = container.querySelector('#trend-axis-foot');

    if (elLblLoad) elLblLoad.textContent = 'DEMANDA AC';
    if (elLblRect) elLblRect.textContent = 'POTENCIA BESS';
    if (elLblBat) elLblBat.textContent = 'CORRIENTE BESS';

    if (elV) elV.textContent = curV.toFixed(1);

    if (elIload) {
      if (loadKw > 0) {
        elIload.textContent = loadKw.toFixed(1);
        if (elUnitLoad) elUnitLoad.textContent = 'kW';
      } else {
        elIload.textContent = (loadKw * 1000 / curV).toFixed(1);
        if (elUnitLoad) elUnitLoad.textContent = 'A';
      }
    }

    var pBessKw = (curV * Math.abs(curIbat) / 1000.0);
    if (elIrect) elIrect.textContent = pBessKw.toFixed(1);
    if (elUnitRect) elUnitRect.textContent = 'kW';

    if (elIbat) elIbat.textContent = Math.abs(curIbat).toFixed(1);
    if (elUnitBat) elUnitBat.textContent = 'A';

    if (elAxisFoot) {
      elAxisFoot.innerHTML = 'Eje Izq: <strong style="color:#38bdf8;">Tensión Bus (V)</strong> | Eje Der: <strong style="color:#f59e0b;">Corriente BESS (A)</strong>';
    }
    if (elReg) elReg.textContent = 'Bus DC 750V Operativo';
  } else {
    var elLblLoad = container.querySelector('#kpi-lbl-load');
    var elUnitLoad = container.querySelector('#kpi-unit-load');
    var elLblRect = container.querySelector('#kpi-lbl-rect');
    var elUnitRect = container.querySelector('#kpi-unit-rect');
    var elLblBat = container.querySelector('#kpi-lbl-bat');
    var elUnitBat = container.querySelector('#kpi-unit-bat');
    var elAxisFoot = container.querySelector('#trend-axis-foot');

    if (elLblLoad) elLblLoad.textContent = 'CARGA BTS';
    if (elUnitLoad) elUnitLoad.textContent = 'A';
    if (elLblRect) elLblRect.textContent = 'RECTIFICADOR';
    if (elUnitRect) elUnitRect.textContent = 'A';
    if (elLblBat) elLblBat.textContent = 'BATERÍA DC';
    if (elUnitBat) elUnitBat.textContent = 'A';

    if (elTitle) elTitle.textContent = 'DINÁMICA DE BUS DC Y CORRIENTES TELECOM';
    var bText = curV > 0 ? ('MODO FLOTACIÓN (' + curV.toFixed(1) + 'V)') : 'BUS DC ESTABILIZADO';
    if (curIbat > 0.5) bText = 'BATERÍA EN CARGA';
    else if (curIbat < -0.5) bText = 'BATERÍA EN DESCARGA';

    if (elBadge) {
      elBadge.textContent = bText;
      elBadge.className = 'trend-badge ' + (curIbat > 0.5 ? 'charging' : 'standby');
    }

    if (elV) elV.textContent = curV > 0 ? curV.toFixed(1) : '--';
    if (elIload) elIload.textContent = curIload.toFixed(1);
    if (elIrect) elIrect.textContent = curIrect.toFixed(1);
    var sIbat = curIbat > 0 ? '+' : '';
    if (elIbat) elIbat.textContent = sIbat + curIbat.toFixed(1);
    if (elAxisFoot) {
      elAxisFoot.innerHTML = 'Eje Izq: <strong style="color:#38bdf8;">Tensión Bus (V)</strong> | Eje Der: <strong style="color:#f8fafc;">Carga BTS (A)</strong> · <strong style="color:#64B856;">Rectif (A)</strong>';
    }
    if (elReg) elReg.textContent = 'Bus DC -48V Telecom Estabilizado';
  }

  self.drawChart();
};

self.drawChart = function() {
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (!container) return;
  var canvas = container.querySelector('#chart-vbat-ibat');
  if (!canvas) return;

  var rect = canvas.getBoundingClientRect();
  var dpr = window.devicePixelRatio || 1;
  var w = rect.width || 400;
  var h = rect.height || 140;
  canvas.width = w * dpr;
  canvas.height = h * dpr;
  var ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);
  ctx.clearRect(0, 0, w, h);

  var curV = self.latestV || 51.1;
  var curIload = self.latestIload || 0;
  var curIrect = self.latestIrect || 0;
  var curIbat = self.latestIbat || 0;
  var isIndustrial = curV > 200.0;

  var now = Date.now();
  var sV = (self.vSeriesData && self.vSeriesData.length > 0) ? self.vSeriesData : [[now - 600000, curV], [now, curV]];
  var sLoad = (self.iLoadSeriesData && self.iLoadSeriesData.length > 0) ? self.iLoadSeriesData : [[now - 600000, curIload], [now, curIload]];
  var sRect = (self.iRectSeriesData && self.iRectSeriesData.length > 0) ? self.iRectSeriesData : [[now - 600000, curIrect], [now, curIrect]];
  var sBat = (self.iBatSeriesData && self.iBatSeriesData.length > 0) ? self.iBatSeriesData : [[now - 600000, curIbat], [now, curIbat]];

  // Escala Eje Izquierdo: Tensión (V)
  var minV, maxV;
  if (isIndustrial) {
    minV = 720; maxV = 800;
  } else {
    var vVals = sV.map(function(p) { return parseFloat(p[1]); }).filter(function(v) { return !isNaN(v) && v > 10; });
    var minVReal = vVals.length > 0 ? Math.min.apply(null, vVals) : curV;
    var maxVReal = vVals.length > 0 ? Math.max.apply(null, vVals) : curV;
    minV = Math.floor(minVReal - 1.5);
    maxV = Math.ceil(maxVReal + 1.5);
    if (maxV - minV < 4) {
      minV = Math.floor(curV - 2);
      maxV = minV + 4;
    }
  }

  // Escala Eje Derecho: Corriente (A)
  var allAmps = [];
  [sLoad, sRect, sBat].forEach(function(s) {
    s.forEach(function(p) {
      var a = parseFloat(p[1]);
      if (!isNaN(a)) allAmps.push(Math.abs(a));
    });
  });
  var maxAReal = allAmps.length > 0 ? Math.max.apply(null, allAmps) : 25.0;
  var maxI = Math.max(isIndustrial ? 300 : 30, Math.ceil(maxAReal * 1.3));
  var minI = 0;

  var padL = 40, padR = 40, padT = 12, padB = 22;
  var plotW = w - padL - padR;
  var plotH = h - padT - padB;
  if (plotW <= 10 || plotH <= 10) return;

  // Rejilla de fondo
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
  ctx.lineWidth = 1;
  for (var r = 0; r <= 3; r++) {
    var y = padT + (plotH / 3) * r;
    ctx.beginPath();
    ctx.moveTo(padL, y);
    ctx.lineTo(w - padR, y);
    ctx.stroke();

    // Etiquetas Eje Izq (V)
    var vLbl = (maxV - ((maxV - minV) / 3) * r).toFixed(1) + ' V';
    ctx.font = '9px -apple-system, sans-serif';
    ctx.fillStyle = '#38bdf8';
    ctx.textAlign = 'right';
    ctx.fillText(vLbl, padL - 5, y + 3);

    // Etiquetas Eje Der (A)
    var iLbl = Math.round(maxI - ((maxI - minI) / 3) * r) + ' A';
    ctx.fillStyle = isIndustrial ? '#f59e0b' : '#64B856';
    ctx.textAlign = 'left';
    ctx.fillText(iLbl, w - padR + 5, y + 3);
  }

  // Marcas de tiempo eje X
  var tMin = sLoad[0][0];
  var tMax = sLoad[sLoad.length - 1][0];
  if (tMax - tMin < 1000) tMin = tMax - 3600000;

  var fmtTime = function(ts) {
    var d = new Date(ts);
    var hh = String(d.getHours()).padStart(2, '0');
    var mm = String(d.getMinutes()).padStart(2, '0');
    return hh + ':' + mm;
  };

  ctx.fillStyle = '#64748b';
  ctx.textAlign = 'left';
  ctx.fillText(fmtTime(tMin), padL, h - 5);
  ctx.textAlign = 'right';
  ctx.fillText(fmtTime(tMax), w - padR, h - 5);

  // Función para trazar curva de datos
  var plotCurve = function(pts, strokeColor, isDashed, lineWidth, isVoltage) {
    if (!pts || pts.length === 0) return;
    ctx.save();
    ctx.beginPath();
    if (isDashed) ctx.setLineDash([5, 4]);
    ctx.lineWidth = lineWidth || 2;
    ctx.strokeStyle = strokeColor;

    for (var i = 0; i < pts.length; i++) {
      var t = pts[i][0];
      var v = parseFloat(pts[i][1]) || 0;
      var x = padL + ((t - tMin) / (tMax - tMin)) * plotW;
      var y;
      if (isVoltage) {
        y = padT + (1 - ((v - minV) / (maxV - minV))) * plotH;
      } else {
        y = padT + (1 - ((v - minI) / (maxI - minI))) * plotH;
      }
      x = Math.max(padL, Math.min(w - padR, x));
      y = Math.max(padT, Math.min(h - padB, y));
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.restore();
  };

  // 1. Tensión de Bus DC (Azul cielo nítido)
  plotCurve(sV, '#38bdf8', false, 2.5, true);

  if (isIndustrial) {
    // 2. Corriente de Batería (Ámbar nítido)
    plotCurve(sBat, '#f59e0b', false, 2, false);
  } else {
    // 2. Corriente de Carga BTS (Blanco nítido)
    ctx.save();
    ctx.shadowColor = 'rgba(255, 255, 255, 0.3)';
    ctx.shadowBlur = 3;
    plotCurve(sLoad, '#ffffff', false, 2, false);
    ctx.restore();

    // 3. Corriente Rectificador (Verde esmeralda punteado)
    plotCurve(sRect, '#64B856', true, 2, false);

    // 4. Corriente de Batería (Ámbar)
    plotCurve(sBat, '#f59e0b', false, 1.5, false);
  }
};

self.onDestroy = function() {};
